#!/bin/bash
set -euo pipefail
app_name=''
app_uuid=''
while getopts ':i:n:s:' opt; do
 case "$opt" in i) app_uuid="$OPTARG" ;; n|s) app_name="$OPTARG" ;; *) exit 64 ;; esac
done
[[ "$(id -un)" == 'emprendeclaro' ]] || exit 77
[[ "$app_name" == 'emprendeclaro_ai_demo_v2' ]] || exit 64
[[ "$(pwd -P)" == '/home/emprendeclaro/apps/emprendeclaro_ai_demo_v2' ]] || exit 77
[[ ! -e ai_wsgi.py && ! -L ai_wsgi.py ]] || exit 73
umask 077
[[ -x /usr/local/bin/python3.11 ]] || exit 69
/usr/local/bin/python3.11 - "$app_uuid" <<'INSTALL_API'
import base64, hashlib, http.client, json, os, pathlib, re, secrets, subprocess, sys, time, urllib.request
root=pathlib.Path.cwd()
app_id=sys.argv[1]
if not re.fullmatch(r'[0-9a-f-]{36}',app_id): raise SystemExit('Invalid app identifier')
host=os.environ.get('API_URL','').replace('https://','').rstrip('/')
if host!='my.opalstack.com': raise SystemExit('Unexpected API host')
token=os.environ.get('OPAL_TOKEN','')
if not token: raise SystemExit('Installer authorization missing')
def opal(method,path,data=None):
    conn=http.client.HTTPSConnection(host,timeout=30)
    conn.request(method,path,None if data is None else json.dumps(data),headers={'Authorization':'Token '+token,'Content-Type':'application/json'})
    response=conn.getresponse(); body=response.read()
    if not 200<=response.status<300: raise SystemExit('Opalstack API HTTP '+str(response.status))
    return json.loads(body) if body else None
app=opal('GET','/api/v1/app/read/'+app_id)
if isinstance(app,list): app=app[0]
port=int(app['port'])
if not 1024<=port<=65535: raise SystemExit('Invalid app port')
payload=base64.b64decode('')
if hashlib.sha256(payload).hexdigest()!='3c836b5e7834cd1dd6a63bdaef9698e962d6027309f3579a21609f8307ff79b8': raise SystemExit('Source checksum mismatch')
(root/'ai_wsgi.py').write_bytes(payload)
(root/'private').mkdir(mode=0o700)
(root/'logs').mkdir(mode=0o700)
(root/'.env').write_text('EMPRENDECLARO_AI_MODE=off\nEMPRENDECLARO_AI_SIGNING_KEY='+secrets.token_urlsafe(48)+'\nEMPRENDECLARO_AI_DATA_DIR='+str(root/'private')+'\n')
subprocess.run([sys.executable,'-m','venv',str(root/'venv')],check=True)
subprocess.run([str(root/'venv/bin/python'),'-m','pip','install','gunicorn==23.0.0'],check=True)
config="""import os
from pathlib import Path
base=Path(__file__).resolve().parent
for line in (base/'.env').read_text().splitlines():
    if line and not line.startswith('#'):
        key,value=line.split('=',1)
        os.environ[key]=value
bind='127.0.0.1:__PORT__'
workers=2
threads=2
timeout=45
pidfile=str(base/'gunicorn.pid')
errorlog=str(base/'logs/error.log')
accesslog=None
capture_output=True
daemon=True
chdir=str(base)
""".replace('__PORT__',str(port))
(root/'gunicorn.conf.py').write_text(config)
start="#!/bin/bash\nset -euo pipefail\ncd /home/emprendeclaro/apps/emprendeclaro_ai_demo_v2\nif [[ -s gunicorn.pid ]] && kill -0 \"$(cat gunicorn.pid)\" 2>/dev/null; then exit 0; fi\nexec ./venv/bin/gunicorn --config gunicorn.conf.py ai_wsgi:application\n"
(root/'start').write_text(start.replace('\\"','"')); (root/'start').chmod(0o700)
subprocess.run([str(root/'venv/bin/gunicorn'),'--config',str(root/'gunicorn.conf.py'),'ai_wsgi:application'],check=True)
for attempt in range(20):
    try:
        with urllib.request.urlopen('http://127.0.0.1:'+str(port)+'/api/status',timeout=3) as response:
            status=json.load(response)
        if status.get('ai_available') is not False: raise SystemExit('Unexpected AI activation')
        break
    except (OSError,ValueError):
        if attempt==19: raise SystemExit('Local health check failed')
        time.sleep(1)
opal('POST','/api/v1/app/installed/',[{'id':app_id}])
print('Bounded AI backend installed; provider access remains disabled.')
INSTALL_API
